// ChatApp.jsx
import React, { useState, useEffect } from "react";
import axios from "axios";
import "./AppLayout.css"; // we'll add styling here

const ChatApp = () => {
  const [chatId, setChatId] = useState("");
  const [message, setMessage] = useState("");
  const [chatLogs, setChatLogs] = useState({});
  const [messages, setMessages] = useState([]);

  const userId = localStorage.getItem("user_id");
  const userEmail = localStorage.getItem("user_email");

  useEffect(() => {
    if (!userId || !userEmail) {
      // Redirect to login page if user is not authenticated
      window.location.href = "/login";
    } else {
      fetchHistory();
      startNewChat(); // Default start
    }
  }, [userId, userEmail]);

  const fetchHistory = async () => {
    try {
      const res = await axios.get(`http://localhost:8000/chat_history/${userId}`);
      const logs = res.data.history;

      // Group messages by chat_id
      const grouped = {};
      logs.forEach((log) => {
        if (!grouped[log.chat_id]) grouped[log.chat_id] = [];
        grouped[log.chat_id].push(log);
      });

      // Sort each session by timestamp
      Object.keys(grouped).forEach(chatId =>
        grouped[chatId].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp))
      );

      setChatLogs(grouped);
    } catch (error) {
      console.error("Error fetching chat history:", error);
    }
  };

  const startNewChat = async () => {
    try {
      const res = await axios.post("http://localhost:8000/new_chat");
      setChatId(res.data.chat_id);
      setMessages([]);
    } catch (error) {
      console.error("Error starting new chat:", error);
    }
  };

  const sendMessage = async () => {
    if (!message.trim()) return;

    try {
      const res = await axios.post("http://localhost:8000/chat", {
        user_id: userId,
        user_email: userEmail,
        message,
        chat_id: chatId,
      });

      const reply = res.data.response;
      const newMsgs = [...messages, { role: "user", text: message }, { role: "ai", text: reply }];
      setMessages(newMsgs);
      setMessage("");
      fetchHistory();
    } catch (error) {
      console.error("Error sending message:", error);
    }
  };

  const loadChat = (chatId) => {
    setChatId(chatId);
    const logs = chatLogs[chatId] || [];
    const sessionMsgs = logs.flatMap(log => [
      { role: "user", text: log.message },
      { role: "ai", text: log.response },
    ]);
    setMessages(sessionMsgs);
  };

  const renderChatTitle = (logs) => {
    const firstMsg = logs.find(log => log.message)?.message || "New Chat";
    return firstMsg.length > 40 ? firstMsg.slice(0, 40) + "..." : firstMsg;
  };

  const handleLogout = () => {
    localStorage.removeItem("user_id");
    localStorage.removeItem("user_email");
    window.location.href = "/login"; // Redirect to login page
  };

  const handleDeleteChat = async (chatId) => {
    try {
      await axios.post("http://localhost:8000/delete_chat", { user_id: userId, chat_id: chatId });
      fetchHistory(); // Refresh chat history
    } catch (error) {
      console.error("Error deleting chat:", error);
    }
  };

  return (
    <div className="app-container">
      <div className="sidebar">
        <button className="new-chat-btn" onClick={startNewChat}>+ New Chat</button>
        <button className="logout-btn" onClick={handleLogout}>Logout</button>
        <div className="chat-history">
          {Object.entries(chatLogs).map(([id, logs]) => (
            <div key={id} className={`chat-title ${chatId === id ? "active" : ""}`} onClick={() => loadChat(id)}>
              {renderChatTitle(logs)}
              <button onClick={() => handleDeleteChat(id)} className="delete-btn">Delete</button>
            </div>
          ))}
        </div>
      </div>
      <div className="chat-area">
        <div className="messages">
          {messages.map((msg, idx) => (
            <div key={idx} className={`message ${msg.role}`}>
              <span>{msg.text}</span>
            </div>
          ))}
        </div>
        <div className="input-area">
          <input
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="Type a message..."
            onKeyDown={(e) => e.key === "Enter" && sendMessage()}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
};

export default ChatApp;
